import itertools
D={}
for a in [-1,-0.5,0,0.5,1,1.5,2]:
    for b in [-1,0,0.5,1,1.5,2,3]:
        if a==0 and b==0: continue
        D[f't^{a}A^{b}']=t**a*A**b
for k in [0.5,1,2]:
    for b in [0,1,2,3]:
        D[f'exp(-{k}t)A^{b}']=np.exp(-k*t)*A**b
for c in [0.25,0.5,0.75,1,1.5,2,3]:
    D[f'exp(-{c}sqrtt)']=np.exp(-c*np.sqrt(t))
    D[f'exp(-{c}sqrtt)A']=np.exp(-c*np.sqrt(t))*A
    D[f'exp(-{c}sqrtt)A^2']=np.exp(-c*np.sqrt(t))*A**2
names=list(D); M=np.column_stack([D[n] for n in names])
y=dA_dt; vy=np.var(y)
best=[]
n=len(names)
for comb in itertools.combinations(range(n),3):
    X=M[:,comb]
    coef,res,rk,_=np.linalg.lstsq(X,y,rcond=None)
    e=np.mean((X@coef-y)**2)/vy
    best.append((e,comb))
best.sort()
for e,comb in best[:6]:
    X=M[:,comb]; coef=np.linalg.lstsq(X,y,rcond=None)[0]
    print(round(e,6),[names[i] for i in comb],np.round(coef,4))

